question_code:
import numpy as np
import pandas as pd

def build_trailing_stop_breakout(df: pd.DataFrame) -> pd.Series:
    prior_high30 = df["close"].rolling(30).max().shift(1)
    running_peak = df["close"].rolling(30).max()

    close_arr = df["close"].to_numpy()
    hi30_arr = prior_high30.to_numpy()
    peak_arr = running_peak.to_numpy()

    out = np.zeros(len(df), dtype=float)
    state = 0
    for i in range(len(df)):
        if state == 0:
            if not np.isnan(hi30_arr[i]) and close_arr[i] > hi30_arr[i]:
                state = 1
        else:
            if close_arr[i] < 0.94 * peak_arr[i]:
                state = 0
        out[i] = state
    return pd.Series(out, index=df.index)

model_full_output:
{
  "has_flaw": true,
  "flaw_types": ["logical_inconsistency"],
  "flawed_location": "running_peak = df[\"close\"].rolling(30).max() and the exit comparison against peak_arr[i]",
  "explanation": "The exit threshold uses a rolling 30-row maximum rather than the highest close since entry. Once a holding-period high ages out of that window, peak_arr can decrease, lowering the stop threshold and allowing the position to remain open despite a drawdown exceeding 6% from its true high-water mark. For example, after entry at 100 followed by 30 closes at 95, a close at 93 should trigger an exit against 94, but the rolling peak is only 95 and its stop threshold is 89.3. Maintain a position-specific peak initialized at entry, updated with max(peak, current_close) while holding, and reset on exit."
}

