question_code:
import numpy as np
import pandas as pd
from src.backtest import Backtest

def build_gradual_scaleout(df: pd.DataFrame) -> pd.Series:
    bull = (df["close"].rolling(20).mean() > df["close"].rolling(50).mean()).to_numpy()
    weights = np.zeros(len(df), dtype=float)
    w = 0.0
    for i in range(len(df)):
        if bull[i]:
            w = 1.0
        else:
            w = max(0.0, round(w - 0.03, 4))
        weights[i] = w
    return pd.Series(weights, index=df.index)

def run_smooth_exit(df: pd.DataFrame) -> pd.DataFrame:
    sig = build_gradual_scaleout(df)
    bt = Backtest(rebalance_tolerance=0.05)
    return bt.run(df, sig)

model_full_output:
{
  "has_flaw": true,
  "flaw_types": ["friction_erosion"],
  "flawed_location": "run_smooth_exit: Backtest(rebalance_tolerance=0.05).run(df, sig) consuming daily 0.03 target-weight decrements",
  "explanation": "The strategy generates daily target weights, not mandatory daily sell orders. Its 3-percentage-point decrements are smaller than the backtest's 5% rebalance tolerance, so the engine can suppress the intended daily reductions. When tolerance is measured against actual holdings, deviations accumulate until a larger rebalance is triggered—for example, with unchanged prices, the 0.97 target is skipped and the 0.94 target triggers an approximately 6-percentage-point sale. Price-driven weight drift can further change execution timing and size. Thus the target schedule does not produce the required daily linear scale-out. Unless zero targets explicitly force liquidation, the tolerance can also leave a residual position. The tolerance must be disabled or configured below the smallest required reduction, including the final liquidation step."
}

