def build_strategy(df):
    import pandas as pd
    import numpy as np

    close = df['close']
    rolling_vol = df['rolling_vol']

    ma50 = close.rolling(window=50).mean()

    signals = pd.Series(0.0, index=df.index)

    current_position = 0.0

    for i in range(len(df)):
        if i < 49:
            # Not enough data for 50-day MA, stay flat
            signals.iloc[i] = 0.0
            current_position = 0.0
            continue

        # Compute ideal position
        vol = rolling_vol.iloc[i]
        if pd.isna(vol) or vol <= 0:
            ideal = 0.0
        elif close.iloc[i] > ma50.iloc[i]:
            ideal = min(0.15 / vol, 1.5)
        else:
            ideal = 0.0

        if ideal == 0.0:
            # Immediately exit
            current_position = 0.0
        elif current_position == 0.0:
            # New entry from flat: directly adopt ideal position
            current_position = ideal
        else:
            # Already in position: only update if change >= 0.15
            if abs(ideal - current_position) >= 0.15:
                current_position = ideal
            # else keep current_position unchanged

        signals.iloc[i] = current_position

    return {
        "signals": signals,
        "slippage_rate": 0.0005,
        "commission_rate": 0.0005,
        "rebalance_tolerance": 0.05,
    }

